        document.getElementById('chat-messages').scrollTop = document.getElementById('chat-messages').scrollHeight;
    }

functions.showTypingIndicator:
function showTypingIndicator() {
        const ind = document.createElement('div'); ind.id = `typing-indicator-${Date.now()}`;
        ind.className = 'bg-slate-200 text-slate-500 rounded-tl-none rounded-2xl mr-auto max-w-[85%] p-3 text-sm shadow-sm flex gap-1 items-center h-10';
        ind.innerHTML = '<div class="w-2 h-2 bg-slate-400 rounded-full typing-dot"></div><div class="w-2 h-2 bg-slate-400 rounded-full typing-dot"></div><div class="w-2 h-2 bg-slate-400 rounded-full typing-dot"></div>';
        document.getElementById('chat-messages').appendChild(ind);
        return ind.id;
    }

functions.handleChatSubmit:
async function handleChatSubmit(e) {
        e.preventDefault(); const input = document.getElementById('chat-input'); const text = input.value.trim(); if (!text) return;
        const sendBtn = e.target.querySelector('button[type="submit"]'); if (sendBtn && sendBtn.disabled) return;
        if (sendBtn) { sendBtn.disabled = true; sendBtn.classList.add('opacity-50', 'cursor-not-allowed'); }
        input.value = ''; appendMessage(text, true); const typingId = showTypingIndicator();
        try {
            const res = await callGeminiAPI(text, standardPrompt);
            document.getElementById(typingId)?.remove(); appendMessage(res, false);
        } finally {
            document.getElementById(typingId)?.remove();
            if (sendBtn) { sendBtn.disabled = false; sendBtn.classList.remove('opacity-50', 'cursor-not-allowed'); }
        }
    }

